#!/usr/bin/env bash
# Verifier driver for step 12 (quiche 0.23.0).
#
# Generated by misc/quic-http3-stack-multiversion/tools/gen-step.py from the
# shared frame plus this step's group list. Edit the frame or the step part and
# regenerate; do not edit one copy in isolation. After Phase 3 opens on a step
# the generated copy becomes authoritative and the reviser edits it directly —
# `tools/carryover-check.sh` is what keeps the fifteen copies honest after that.
set -u
source /tests/helpers.sh

# --- verifier/step binding check -------------------------------------------
# Must be the first thing that runs: /etc/harbor-step-id names the image, the
# literal below names this tests/ tree, and a disagreement means the build
# context was served from another step's cache entry.
require_step 12
# --- end binding check ------------------------------------------------------

# ---------------------------------------------------------------------------
# 0. Crash path.
#
# Under `multi_step_reward_strategy = "mean"` a verifier that exits without a
# reward.json costs the whole trial the steps after it, so every exit from here
# on writes a complete scorecard and exits 0. `fail_everything` is the
# scorecard for a driver that died before it could measure anything.
#
# It reports `gate: 0` with an empty `gate_failures`, and that pairing is the
# signal: a gate of zero with no group named is the driver failing, not a
# candidate regressing. Anything that vetoes a real step names the group and
# quotes what it saw.
# ---------------------------------------------------------------------------
reported=0

fail_everything() {
    local reason="$1"
    printf '{"step":%s,"reward":0.000000,"gate":0,"score":0.000000,"gate_failures":[],"candidate_build":0,"harness_build":0,"fixture_ok":0,"budget_exhausted":0,"crate_dir":"unresolved","build_note":"%s","gate_groups":{},"scored_groups":{}}\n' \
        "${step_num:-0}" "$reason" > /logs/verifier/reward_details.json
    printf '{"reward":0.000000}\n' > /logs/verifier/reward.json
}

on_exit() {
    local status=$?
    if [ "${reported:-0}" -ne 1 ]; then
        fail_everything "the verifier driver exited with status $status before it reported: nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    fi
    exit 0
}
trap on_exit EXIT

step_num=12
step_tag=0.23.0
log_dir=/tmp/quiche-verifier-12
harness=/tmp/quiche-harness-12
assets=/tests/assets
mkdir -p "$log_dir"

# ---------------------------------------------------------------------------
# 1. Fixture integrity.
#
# The verifier-owned corpus — the RFC 9001 Appendix A vectors, the frame and
# QPACK vector files, and the e2e drivers — is a prerequisite for the groups
# that consume it, never a score point of its own. A broken corpus fails those
# groups; it must not short-circuit the independent ones or erase earned
# credit.
# ---------------------------------------------------------------------------
expected_assets_sha=398a11715b6f67c2bc29e8d187715f8cf8735487b1a31d245059e4794355a5e0
expected_asset_files=35

actual_assets_sha=$(cd "$assets" && find . -type f -print0 | LC_ALL=C sort -z \
    | xargs -0 sha256sum | sha256sum | awk '{print $1}')
actual_asset_files=$(find "$assets" -type f | wc -l)

fixture_ok=1
[ "$actual_assets_sha" = "$expected_assets_sha" ] || fixture_ok=0
[ "$actual_asset_files" -eq "$expected_asset_files" ] || fixture_ok=0

# ---------------------------------------------------------------------------
# 2. Locating the candidate's transport crate.
#
# The library lives at the workspace root until milestone 6 and under
# `quiche/` from milestone 6 onward. Both layouts are accepted everywhere and
# the layout itself is scored by its own group at the step that introduces it,
# so a candidate that has not yet moved the tree loses that one group rather
# than every group in the step. TEST_INTERFACE.md states this probe.
# ---------------------------------------------------------------------------
crate_dir=unresolved
for cand in /app/quiche /app; do
    if [ -f "$cand/Cargo.toml" ] && grep -Eq '^[[:space:]]*name[[:space:]]*=[[:space:]]*"quiche"' "$cand/Cargo.toml"; then
        crate_dir=$cand
        break
    fi
done

workspace_root=/app
[ -f /app/Cargo.toml ] || workspace_root=$crate_dir

# ---------------------------------------------------------------------------
# 2. (continued) Which BoringSSL this tree was written against.
#
# The image pins the library this milestone's release pins, and the environment
# names it. At most steps that is the only copy and this loop does nothing.
#
# Where the QUIC callback struct changed shape across a step boundary, the
# image carries the previous release's pin as well. `SSL_QUIC_METHOD` is a
# struct of function pointers passed to `SSL_set_quic_method`: releases up to
# 0.1.0 declare four members, beginning `set_encryption_secrets`; from 0.3.0
# they declare five, beginning `set_read_secret` and `set_write_secret`. A tree
# of the older shape handed to a library of the newer one links cleanly -- the
# symbol exists and takes a pointer -- and then reads one member past the end
# of the struct, calling the wrong function for every callback. Nothing errors.
# The handshake simply never emits a ClientHello, and the step's inherited
# regression groups fail for a linkage reason wearing behaviour's clothes.
#
# So the shape is read out of the candidate's own `src/tls.rs` and the matching
# library selected. The test is deliberately two-sided -- the old name present
# AND the new names absent -- so a tree part-way through the conversion, or one
# that merely mentions the old name in a comment, keeps this release's library.
# The shape is read out of *live code*: `//` comments are stripped before the
# two greps run, so a migration note naming the old field cannot flip the pick.
# A candidate who does the work is unaffected: the environment already names
# the right one, and this loop never fires. It cannot manufacture a pass for
# the scored groups either; those ask for behaviour this milestone introduced,
# which no older library supplies.
#
# `.cargo/config.toml` in the workdir sets the same variable through cargo's
# `[env]` table, which without `force = true` yields to a variable already set
# in the environment -- so exporting here is enough, and the file stays honest
# about the default.
# ---------------------------------------------------------------------------
if [ -n "${QUICHE_BSSL_PATH:-}" ] && [ -f "$crate_dir/src/tls.rs" ] &&
    sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_encryption_secrets' &&
    ! sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_read_secret'; then
    for alt in /opt/bssl/*; do
        [ -d "$alt" ] || continue
        [ "$alt" = "$QUICHE_BSSL_PATH" ] && continue
        QUICHE_BSSL_PATH=$alt
        export QUICHE_BSSL_PATH
        break
    done
fi

# ---------------------------------------------------------------------------
# 2a. The time budget, and why these numbers.
#
# `task.toml` gives this step `[steps.verifier] timeout_sec = 3600`. If the
# verifier is killed by that timeout it never writes reward.json and the run is
# unattributable rather than a zero, so the work inside must provably fit
# whatever the candidate does:
#
#   verify the pinned asset corpus                               <   5 s
#   CANDIDATE_BUILD_TIMEOUT  one `cargo build` of /app, cold    <= 1000 s
#   EXAMPLES_BUILD_TIMEOUT   the best-effort examples pass      <=  240 s
#   APPS_BUILD_TIMEOUT       the best-effort app-package pass   <=  240 s
#   HARNESS_BUILD_TIMEOUT    one `cargo test --no-run` of the
#                            verifier-owned harness crate       <=  800 s
#   CASE_BUDGET_TOTAL        every gate check and every scored
#                            group together                     <= 1200 s
#   write the two JSON files                                     <   5 s
#                                                    worst case   3490 s
#
# PER_CASE_MAX is far above any real case and far below the aggregate: one
# hanging case costs its own group and at most 120 s of the shared pool, so a
# step with many hanging cases degrades group by group instead of taking the
# run down. BoringSSL and the whole dependency graph are prebuilt into the
# image, so the candidate build is the candidate's own code and nothing else.
CANDIDATE_BUILD_TIMEOUT=1000
EXAMPLES_BUILD_TIMEOUT=240
APPS_BUILD_TIMEOUT=240
HARNESS_BUILD_TIMEOUT=800
CASE_BUDGET_TOTAL=1200
PER_CASE_MAX=120

# ---------------------------------------------------------------------------
# 3. Build the candidate workspace once, before anything is scored.
#
# Recorded separately from the groups: every group runs against this build, so
# one compile error would otherwise be reported as N unrelated capability gaps.
# ---------------------------------------------------------------------------
candidate_build=0
if [ "$crate_dir" != unresolved ]; then
    # Default targets only -- libraries and binaries. Deliberately not
    # `--all-targets`: that would also compile the candidate's own test and
    # bench targets, so a broken test of theirs would fail the build and be
    # reported as every capability missing at once. Their tests are not what
    # this verifier measures.
    (cd "$workspace_root" && timeout "$CANDIDATE_BUILD_TIMEOUT" \
        cargo build --offline -j 4) \
        >"$log_dir/candidate-build.log" 2>&1 && candidate_build=1
    # The client and server lived under examples/ before they became their own
    # package. Best-effort and never fatal: at releases where they are bins the
    # build above already produced them, and at releases where there are no
    # examples this is a no-op.
    if [ "$candidate_build" -eq 1 ]; then
        (cd "$workspace_root" && timeout "$EXAMPLES_BUILD_TIMEOUT" \
            cargo build --offline --examples -j 4) \
            >"$log_dir/candidate-examples.log" 2>&1 || true
    fi
    # Later they moved out of examples/ and into a package of their own --
    # `tools/apps` first, then `apps`. Where that package is a workspace member
    # the build above already covered it; where it exists but the root manifest
    # has no [workspace] section, cargo never descends into it, so the tree
    # ships the client and server sources and produces neither binary. Building
    # the package where it sits covers that window, and builds more of the
    # candidate rather than asking less of it.
    #
    # Best-effort, like the examples pass, and bounded as one pass rather than
    # one per path: at a release whose lockfile predates this package's own
    # dependencies it cannot resolve offline at all, which is a property of the
    # pinned corpus and not a candidate defect. Building a non-member package
    # makes cargo write a lockfile beside its manifest; no group reads one.
    if [ "$candidate_build" -eq 1 ]; then
        apps_deadline=$(( $(date +%s) + APPS_BUILD_TIMEOUT ))
        for app in tools/apps apps; do
            [ -f "$workspace_root/$app/Cargo.toml" ] || continue
            left=$(( apps_deadline - $(date +%s) ))
            [ "$left" -gt 0 ] || break
            (cd "$workspace_root/$app" && timeout "$left" \
                cargo build --offline -j 4) \
                >"$log_dir/candidate-app-$(printf '%s' "$app" | tr / -).log" \
                2>&1 || true
        done
    fi
fi

# The client and server binaries are the process boundary most groups use.
# The harness resolves them itself, by name, from the CANDIDATE_* variables
# below -- the names are the step's own interface section's, and the harness
# applies them name-major over the directories it searches. The driver does
# not pre-resolve a binary and does not prefer any spelling of its own: a
# second resolution rule written here could only ever disagree with that one.
target_dir=${CARGO_TARGET_DIR:-$workspace_root/target}

export QUICHE_CRATE_DIR="$crate_dir"
export QUICHE_WORKSPACE="$workspace_root"
export QUICHE_ASSETS="$assets"
export QUICHE_LOGDIR="$log_dir"

# What `verifier::testkit` reads. The harness has to find the candidate's
# binaries, and in this image they are not under /app/target: CARGO_TARGET_DIR
# is set image-wide so the prewarmed dependency graph is reused, which moves
# every artefact to /opt/cargo-target. Telling the harness where the tree and
# the artefacts actually are keeps that an image detail instead of something
# each of the fifteen steps' test files has to know.
export CANDIDATE_ROOT="$workspace_root"
export CANDIDATE_TARGET_DIR="$target_dir"
# Scratch directories are deliberately never cleaned up: when a case fails, the
# document root, the captured stdout and the server log it left behind are the
# evidence. Rooting them in the log directory keeps them beside the case log.
export VERIFIER_SCRATCH="$log_dir/scratch"
mkdir -p "$VERIFIER_SCRATCH"

# ---------------------------------------------------------------------------
# 4. The throw-away harness crate.
#
# It lives outside /app so that a candidate cannot make its own acceptance pass
# by editing the cases, and so that nothing the harness needs is ever added to
# the candidate's manifest. It declares exactly one dependency — a path
# dependency on the candidate's own transport crate — so a harness build
# failure is always about the candidate's public surface and never about a
# registry.
# ---------------------------------------------------------------------------
# Does the candidate's manifest declare a Cargo feature by this name?
#
# Either an explicit entry under [features], or an optional dependency of the
# same name, which Cargo turns into a feature implicitly.
# Does the candidate's manifest declare `$2` as a feature?
#
# Three spellings are legal Cargo for "this crate can be built with a `qlog`
# feature", and all three have to be recognised or a correct manifest is read
# as not declaring it, the feature is dropped from the harness's own edge, and
# every `cap` group fails to link for a reason that is not the candidate's:
#
#   [features]
#   qlog = []
#
#   [dependencies]
#   qlog = { version = "..", optional = true }
#
#   [dependencies.qlog]
#   optional = true
#
# The third puts the name in the section header and never in field 1, which is
# why the spelling is tracked as well as the key.
declares_feature() {
    awk -v want="$2" '
        /^[[:space:]]*\[/ {
            sec = $1
            gsub(/^\[|\]$/, "", sec)
            section = sec
            dep_table = (sec == "dependencies." want || sec == "dev-dependencies." want \
                         || sec == "build-dependencies." want)
            next
        }
        $1 == want && $2 == "=" && section == "features" { found = 1 }
        $1 == want && $2 == "=" && section ~ /dependencies$/ \
            && $0 ~ /optional[ \t]*=[ \t]*true/ { found = 1 }
        dep_table && $1 == "optional" && $2 == "=" && $3 == "true" { found = 1 }
        END { exit found ? 0 : 1 }
    ' "$1"
}

prepare_harness() {
    rm -rf -- "$harness"
    mkdir -p "$(dirname "$harness")"
    # The whole tree, not a hand-listed subset: the harness is a two-member
    # workspace (the verifier crate and `support/`, the independent QUIC
    # implementation) and it carries its own `assets/` — the TLS keypair and
    # the RFC vectors the cases load through `testkit::asset`. Copying file
    # patterns instead would silently drop whichever of those a future step
    # starts using, and the resulting build failure would be charged to the
    # candidate.
    cp -a -- "$assets/harness" "$harness"
    # The only edit: the candidate's crate path, which is not known until the
    # probe above has run. Resolved here rather than in the checked-in manifest
    # so the manifest stays identical in all fifteen steps.
    sed -i "s#@@CRATE_DIR@@#$crate_dir#g" "$harness/Cargo.toml"
    # Optional feature requests, resolved against the candidate's own manifest.
    #
    # Cargo validates every feature reference while it resolves the graph,
    # before it compiles anything, so asking a milestone for a feature it does
    # not declare fails the whole harness build -- including the gate targets,
    # which never touch the feature. Names marked `# optional-feature:` in the
    # harness manifest are therefore kept only when the candidate declares
    # them. The scored case that needs one then fails to compile by itself,
    # which is the right answer for a candidate that has not built it.
    for feat in $(sed -n 's/^#[[:space:]]*optional-feature:[[:space:]]*//p' \
        "$harness/Cargo.toml"); do
        if declares_feature "$crate_dir/Cargo.toml" "$feat"; then
            printf 'kept optional feature %s\n' "$feat" \
                >>"$log_dir/harness-features.log"
        else
            sed -i "s/\"$feat\"[[:space:]]*,[[:space:]]*//; s/,[[:space:]]*\"$feat\"//; s/\"$feat\"//" \
                "$harness/Cargo.toml"
            printf 'dropped optional feature %s: the candidate does not declare it\n' \
                "$feat" >>"$log_dir/harness-features.log"
        fi
    done
    # No lockfile, on purpose. One authored against the reference tree would
    # pin the candidate's own dependency versions, turning a legitimate
    # difference in their manifest into a harness build failure that reads as
    # their fault. The registry cache is prewarmed, so resolving offline here
    # costs nothing.
    rm -f -- "$harness/Cargo.lock"
}

harness_build=0
if [ "$candidate_build" -eq 1 ]; then
    prepare_harness
    (cd "$harness" && timeout "$HARNESS_BUILD_TIMEOUT" \
        cargo test --offline --no-run -j 4) \
        >"$log_dir/harness-build.log" 2>&1 && harness_build=1
fi

# The case pool starts here, so a slow build cannot eat it.
case_deadline=$(( $(date +%s) + CASE_BUDGET_TOTAL ))
budget_exhausted=0

# remaining_budget -> seconds left in the shared pool, or 0
remaining_budget() {
    local r=$(( case_deadline - $(date +%s) ))
    [ "$r" -lt 0 ] && r=0
    printf '%s\n' "$r"
}

# run_case <log-name> <test-target> <test-fn>
#
# Each case is bounded by the smaller of PER_CASE_MAX and what is left of
# CASE_BUDGET_TOTAL, so the cases can never overrun that total however many of
# them hang. A killed case exits non-zero and scores that one group 0, which is
# the same outcome as any other failure; once the pool is spent the remaining
# groups are failed without running and the reason is recorded, which is still a
# zero rather than a lost run.
run_case() {
    local name="$1" target="$2" fn="$3" remaining limit status
    remaining=$(remaining_budget)
    if [ "$remaining" -le 5 ]; then
        budget_exhausted=1
        printf 'the aggregate case budget of %s s was exhausted before this case ran\n' \
            "$CASE_BUDGET_TOTAL" >"$log_dir/$name.log"
        return 1
    fi
    if [ ! -d "$harness" ]; then
        # The harness crate is assembled only after a candidate transport crate
        # has been located. When it was not, every case here would fail on `cd`
        # with a shell error in its log, which reads as a broken driver rather
        # than as a result. The group does fail -- but for a definite reason,
        # and the reason belongs on the group that fired it.
        {
            printf 'the harness crate was never assembled, so this case could not run.\n'
            printf 'assembly is skipped when no candidate transport crate was located\n'
            printf '(crate_dir=%s): there was nothing for the harness to link against.\n' "$crate_dir"
            printf 'This group fails for that reason, not for anything it asserts.\n'
        } >"$log_dir/$name.log"
        return 1
    fi
    limit=$PER_CASE_MAX
    [ "$remaining" -lt "$limit" ] && limit=$remaining
    (cd "$harness" && timeout "$limit" \
        cargo test --offline --test "$target" "$fn" -- --exact --nocapture) \
        >"$log_dir/$name.log" 2>&1
    status=$?
    [ "$status" -eq 0 ] || return "$status"
    # Every invocation asserts an exact executed count: a name filter that
    # matches nothing still exits 0, and would otherwise be scored as a pass.
    grep -q 'test result: ok\. 1 passed; 0 failed; 0 ignored' "$log_dir/$name.log"
}

# ---------------------------------------------------------------------------
# 5. The gate.
#
# Proof of life plus inherited regression: that the candidate builds, that its
# two binaries still complete a handshake and a transfer over real UDP, and
# that one deterministic end-to-end path per earlier milestone still works.
#
# Gate groups earn nothing. They only veto: if any one of them fails the step
# is worth zero however much of this step's own capability landed. That is
# deliberate. A candidate that implements this release by breaking the last one
# has not advanced the ladder, and an additive score would pay it for the parts
# that still happen to work.
#
# The corollary governs what is allowed in here. A gate case that can fail for
# a reason other than the candidate's code -- a wall clock, a host's CPU count,
# an unordered iteration read as ordered -- is not weak coverage, it is a step
# that randomly scores zero for everyone including the reference. Every case
# below is deterministic, and the ones that were not were deleted rather than
# demoted; NOTES.md lists them and why.
#
# Behaviour this step deliberately changes is likewise not in here. A migration
# left in the gate is a step whose own reference implementation fails it.
# ---------------------------------------------------------------------------
gate_ok=1
gate_log=$log_dir/gate.txt
: > "$gate_log"

gate_check() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$gate_log"
    else
        printf 'FAIL %s\n' "$name" >> "$gate_log"
        gate_ok=0
    fi
}

candidate_builds() { [ "$candidate_build" -eq 1 ]; }

# Every other gate group is a case or a driver and leaves `$log_dir/<name>.log`
# behind, which is where the scorer reads the reason a veto fired. This one is
# a flag set back in section 3, so give it the log the flag came from.
if [ -f "$log_dir/candidate-build.log" ]; then
    cp -f "$log_dir/candidate-build.log" "$log_dir/candidate-workspace-builds.log"
else
    # Section 3 runs cargo only when a quiche crate was located. When it was
    # not, no candidate-build.log exists, and copying it silently left this
    # group with no log at all -- which the scorer reports as "the case did not
    # run". That reads like a harness that failed to fire, when in fact the
    # group failed for a definite reason. A veto must carry its reason on the
    # group that fired it, so write it here rather than leave the scorer to
    # guess. The step-level build_note says the same thing; this puts it where
    # a reader looks first.
    {
        printf 'no cargo build was attempted: crate_dir=%s\n' "$crate_dir"
        printf 'no Cargo.toml declaring the package name `quiche` was found at\n'
        printf '/app or /app/quiche, so there was no transport crate to build.\n'
        printf 'This group fails by definition: proof-of-life cannot pass when\n'
        printf 'the candidate shipped no library to prove alive.\n'
    } > "$log_dir/candidate-workspace-builds.log"
fi
gate_check candidate-workspace-builds candidate_builds
# T3: Carried as the previous milestone's headline. Both endpoints are configured with `set_max_send_udp_payload_size(1452)` and `set_max_recv_udp_payload_size(1452)`, and the only thing that differs between the two legs is `discover_pmtu`: * **on** -- at least one **server** datagram is exactly 1452 bytes, and every server datagram is either at or under 1200 or exactly 1452, with nothing in between; * **off** -- no server datagram exceeds 1200 at all; * **both** -- a 64 KiB body arrives byte-for-byte with the stream finished, and neither end of the on-configuration pair is closed afterwards. Carried because this step adds a workspace member that opens its own connections and a setter that re-encodes a live connection's transport parameters, and because PMTU discovery is the youngest behaviour in the stack -- a rebuild of the send path would show here first. **Three of step 11's legs are deliberately left behind**, and each for the same reason: a gate case is an unpriced veto, so anything in it that could read differently under load costs every candidate the whole step. * The **probe count and position** were never asserted at step 11 either, and are not asserted here. * The **client histograms** -- `{43:1, 483:1, 904:1, 936:1, 1050:1, 1200:54}` with discovery on against `{43:1, 483:1, 932:1, 962:1, 1452:45}` with it off -- are dropped. They are a statement about how a 64 KiB write is chopped up, which depends on the congestion window at each `send`, and the exact multiset is not something a gate should be asserting. The *bound* survives in the server legs above, where it is one-sided. * The **binary-search-on-loss** leg was already absent at step 11, for the reason recorded there: the reference needed more timer ticks than a bounded case can justify before it re-probed at a smaller size. `PathStats::pmtu` is not read, at step 11 or here: it reports the *configured* maximum from the moment the connection is created and reads 1452 in both legs before either has sent a packet, so it cannot tell them apart.
gate_check reg-11-pmtud run_case reg-11-pmtud reg reg_11_pmtud
# T2: The verifier becomes the peer that initiates the update, because there is no public API for initiating one and the candidate is only required to implement the responder: from `CLIENT_TRAFFIC_SECRET_0` in the candidate's own keylog it derives the next generation itself -- HKDF-Expand-Label with `quic ku`, then `quic key` and `quic iv` -- and builds a protected 1-RTT packet with the key- phase bit set. It proves those keys first by opening one of the candidate's own packets with them, so that a key-schedule disagreement cannot read as a candidate fault. Then: the candidate decrypts the injected STREAM frame and `stream_recv` returns the payload byte-for-byte; its own next packet has the phase bit set; and a second update before the first is acknowledged is `Err(Error::KeyUpdate)`. Carried because this step's new setter re-encodes a live connection's transport parameters and its new workspace member drives connections of its own, and every short-header packet either of those produces is sealed by exactly this machinery. The header-protection reuse leg is implied rather than separately asserted, as at step 09: the verifier applies header protection with the generation-0 key, so a candidate that rotated it could not find the packet number and nothing later would succeed.
gate_check reg-09-key-update run_case reg-09-key-update reg reg_09_key_update
# T1: Inherited from step 01, re-seeded from step 07, the most recent step to carry it: a 64 KiB body travels from the candidate's own `quiche-server` to the candidate's own `quiche-client` over UDP loopback, byte for byte, as two real processes, with `--http-version HTTP/3` pinned so the observation stays HTTP/3 rather than whatever the apps would negotiate. Carried because this step reaches into the HTTP/3 layer twice -- a new way to send header sections and a new statistics surface -- and because it is the only inherited gate case here that exercises the whole stack as the user gets it. `cap-h3i-replay` also crosses the process boundary, but through a new binary and against a hand-written action file; this one is the ordinary path, and if it fails, that one's diagnosis is guesswork.
gate_check reg-01-h3-get run_case reg-01-h3-get reg reg_01_h3_get
# T1: The mandatory process-boundary gate. The candidate's own `quiche-server` is started on a loopback port with `--listen`, `--cert`, `--key`, `--root` and `--no-retry`; the candidate's own `quiche-client` fetches a 2 KiB body from it over real UDP with `--no-verify`; the client exits zero and the bytes match what the server was given. Everything else is the reference's own default -- version 1, ALPN negotiated from the app's own list, HTTP/3 alongside HTTP/0.9. Nothing about this step's milestone appears here: no `h3i`, no live idle timeout, no transport-parameter tracking. That is the point. If this group fails, every other T1 observation at this step is noise.
gate_check gate-endtoend run_case gate-endtoend gate gate_endtoend

# ---------------------------------------------------------------------------
# 6. The scored groups.
#
# This step's new capability, plus peripheral breadth. Each group is one
# coherent behaviour and is invoked separately, so a failure localises, and
# every group runs even after another has failed: a partial implementation
# keeps exactly the credit it earned.
#
# Weights live in `/tests/groups.json` and sum to one across the groups here,
# so this step's score is in [0, 1] and is the weighted fraction of its own new
# behaviour that works. Nothing in this section knows a weight -- it records
# PASS or FAIL per group and the scorer prices it -- so a revision that edits a
# group here cannot silently desync the driver from the manifest.
# ---------------------------------------------------------------------------
group_log=$log_dir/groups.txt
: > "$group_log"

score_if() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$group_log"
    else
        printf 'FAIL %s\n' "$name" >> "$group_log"
    fi
}

# T1: Three of the candidate's own processes' worth of work in one: its `quiche-server` is started on a loopback port with `--listen`, `--cert`, `--key`, `--root` and `--no-retry` and with `QLOGDIR` pointing at an empty scratch directory; its `h3i` binary is given a two-record JSON-SEQ action file and told to replay it at that port; and the **server's** qlog is read to see what arrived. The action file is written by the verifier, not by the candidate, and is the shape the interface document fixes: a `0x1E`-prefixed header record naming `qlog_version 0.3`, `qlog_format JSON-SEQ` and a client vantage point, then a `0x1E`-prefixed `http:frame_created` record carrying a `headers` frame on stream 0 with `:method GET`, `:scheme https`, `:authority`, a `:path` naming a file the docroot contains, and `"fin_stream": true`. `h3i` is invoked as `h3i --qlog-input <file> --no-verify --connect-to 127.0.0.1:<port> --idle-timeout <ms> <authority>:<port>`, and must exit 0 within the group's deadline. Exiting 0 is the first half of the assertion and is not sufficient on its own: a binary that parsed its arguments and connected to nothing would also exit 0, which is why the second half reads the server. What the server's `.sqlog` must show, matched as qlog event names and their payloads rather than as log prose: the HEADERS frame arriving on stream 0 with the `:path` the action file named, and a response going back on the same stream. Assertions are on the server's qlog because that is an emitted artefact with a schema; `h3i`'s own stderr is a `log`-crate format that nothing in this step declares, and a group that grepped it would be scoring a logging convention. Three failure modes were seen while proving this shape and each is asserted against rather than assumed away: `h3i` absent from the workspace member list, so the binary is never built (the group then fails on the missing binary, and says so); `--qlog-input` pointed at a file that does not exist, which the reference answers with a panic rather than a diagnostic, so the file is written before the process starts and its path is absolute; and the authority in the replayed headers not matching what the server will serve, which `--replay-host-override` exists to fix and which the verifier avoids by writing the same authority into both. Not asserted, and each for a reason rather than by omission: * the interactive prompt mode, the connection summary's wording, the `h3i` qlog *output* file, and any frame the action file did not ask for; * **`--replay-host-override` itself.** The paragraph above explains what it is for; the verifier sidesteps the problem instead, by writing the same authority into the replayed headers and into what the server serves. The flag must exist and take an argument -- a candidate that omits it from the usage string has not built this milestone's `h3i` -- but no group drives it, and that is a choice, not an oversight; * **the default value of `--idle-timeout`.** It is 5000 ms, and the contract above says so because a candidate has to pick a number. Every invocation in this package passes the flag explicitly (2000 ms), so the default is never the value in play. Proving it would mean running one replay with the flag omitted and waiting for the connection to idle out on its own -- five seconds of wall clock, per run, to pin a number nothing else depends on. Documented, not asserted.
score_if cap-h3i-replay run_case cap-h3i-replay cap cap_h3i_replay
# T3: Two in-memory `connect`/`accept` pairs that differ in exactly one line, read from the side that can actually see the answer. Both configurations set `Config::set_max_idle_timeout(30_000)` on **both** ends. In the first pair, and only there, the client is then told `set_max_idle_timeout(7_000)` on the **connection**, immediately after `quiche::connect` and before a single datagram has been produced. Both pairs then handshake normally. Measured against the reference: | | server's view of the client | client's view of the server | | --- | --- | --- | | live call made | **7000** | 30000 | | no live call | 30000 | 30000 | Three separate things are being pinned by those four numbers. That the server sees 7000 is the feature. That the *client's* view of the *server* stays 30000 in the same pair is what stops a candidate from having changed a shared default. And that the baseline pair reports 30000 on the same code path is what stops the first row from being satisfied by a connection that ignores its config. The value is read through `Connection::peer_transport_params()`, which the previous milestone already provided -- so the group is about the new setter and not about a new way of looking. The return type is load-bearing and is exercised, not merely mentioned: the call site binds the result and propagates it, so a candidate whose method returns `()` does not compile. It is not required to fail, and no case provokes the error path. Deliberately not asserted: that a call made *after* the first packet is rejected. The documentation says "must only be called immediately after creating a connection", and the reference enforces nothing -- it writes the field and re-encodes whenever it is asked. Requiring a rejection would require the candidate to be stricter than the reference. Deliberately not asserted either: anything about a connection actually timing out. Idle timeout expiry is a wall-clock observation and has no place in a case that must be deterministic.
score_if cap-live-idle-timeout run_case cap-live-idle-timeout cap cap_live_idle_timeout
# T3: One handshake, both answers. The **server's** config calls `enable_track_unknown_transport_parameters(128)`; the **client's** does not. Everything else is the pair's default. After an ordinary handshake, read through `Connection::peer_transport_params()`: * the server's view of the client is `Some(u)` with `u.capacity == 128` and `u.parameters` **empty**; * the client's view of the server is `None`. Measured against the reference, exactly: `Some(UnknownTransportParameters { capacity: 128, parameters: [] })` and `None`. That is the whole group, and it is deliberately small. The record is allocated while the peer's parameter block is being decoded, from the configuration alone, before any parameter has been examined -- so its existence and its declared capacity are observable even though this ladder's peer sends nothing unrecognised. `None` and an empty `Some` are different answers to different questions, and a candidate that returns `Default::default()` for both, or `Some(empty)` for both, fails one half or the other. A second capacity is not tested here and does not need to be: the arithmetic belongs to `cap-unknown-tp-capacity`, where it is exercised directly on the public type instead of through a handshake. Not observed anywhere in this step: a tracked parameter that actually arrived. Both endpoints of the pair are the candidate, the candidate emits no unrecognised transport parameter, and the verifier's support crate has no TLS and so cannot complete a handshake to send one. The narrowing is real and is recorded rather than papered over with a group that hand-builds a `TransportParams` and asserts on its own struct literal.
score_if cap-unknown-tp-tracking-enabled run_case cap-unknown-tp-tracking-enabled cap cap_unknown_tp_tracking_enabled
# T3: The public accounting type, driven directly. No connection, no handshake, nothing timed: `UnknownTransportParameters { capacity: 20, parameters: vec![] }` is built by the verifier -- both fields are public and the type derives `Default` -- and then pushed into, in this order. Measured against the reference: | push | charge | admitted? | capacity after | entries after | | --- | --- | --- | --- | --- | | `{ id: 31, value: b"abcd" }` | 4 + 8 = 12 | yes, `12 < 20` | 8 | 1 | | `{ id: 62, value: b"abcd" }` | 12 | **no**, `12 < 8` is false | 8 | 1 | | `{ id: 63, value: b"" }` | 0 + 8 = 8 | **no**, `8 < 8` is false | 8 | 1 | Four claims, and the third row is the one that matters most. The admission test is a **strict** `<`, so an entry whose charge exactly equals the remaining capacity is refused; a candidate that wrote `<=` passes the first two rows and fails the third. The eight bytes charged for the identifier are fixed and are charged even for an empty value, which is what the third row also shows. Both refusals return `Err` -- `BufferTooShort` -- and both leave `capacity` and `parameters` exactly as they were. A silent drop at this API would be a different contract from the quiet drop the protocol layer performs, and the group asserts the state after each refusal rather than only the return value. The surviving entry is then read back through the `IntoIterator` on `&UnknownTransportParameters`, yielding one item whose `id` is 31 and whose `value` is `b"abcd"` -- so a candidate that accounted correctly but stored nothing, or stored a borrowed slice it could not return, fails here.
score_if cap-unknown-tp-capacity run_case cap-unknown-tp-capacity cap cap_unknown_tp_capacity
# T3: `UnknownTransportParameter::is_reserved` over a fixed table, and nothing else. RFC 9000 Section 18.1 reserves the identifiers `31 * N + 27` for parameters that have no meaning and must always be ignored; the predicate is true for exactly those. The table, measured against the reference: | id | 27 | 28 | 31 | 57 | 58 | 62 | 88 | 89 | 90 | 119 | 120 | 121 | 1000 | 7963 | | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | | reserved | Y | n | n | n | Y | n | n | Y | n | n | Y | n | n | Y | Five true, nine false, the true ones being 27, 58, 89, 120 and 7963 -- the first four members of the family and one well above where an off-by-one in a loop would still agree -- and the false ones chosen to sit immediately on either side of a true one (28, 57, 88, 90, 119, 121) so that a predicate off by one in either direction fails. **Identifiers below 27 are deliberately absent, and this is not an oversight.** The reference computes `(id - 27) / 31` on a `u64`, which underflows for every identifier under 27 and panics outright in the debug profile the verifier builds -- `id: 0` was measured taking the whole probe down at `quiche/src/lib.rs:8085`. A candidate writing the obvious non-underflowing form, `id >= 27 && (id - 27) % 31 == 0`, answers `false` there instead. RFC 9000 Section 18.1 defines the reserved set only upward from 27 and says nothing about what lies below, so both readings are defensible and neither is this milestone's capability. Scoring the difference would score an arithmetic accident of the reference rather than the feature; the table stops at 27 and the two forms agree on every row of it. Weight 1: this is a pure predicate over a public type, peripheral to the tracking machinery that `cap-unknown-tp-tracking-enabled` and `cap-unknown-tp-capacity` carry.
score_if cap-tp-reserved-ids run_case cap-tp-reserved-ids cap cap_tp_reserved_ids
# T3: An HTTP/3 exchange over an in-memory pair in which the response arrives in two header sections, and a client that tries the same thing is refused. The server answers a GET with `send_response(103, [link: </s.css>], fin=false)` -- the informational section, which is the stream's *initial* header section and so goes out through the ordinary call -- and then `send_additional_headers(&[:status 200, content-length: 5], is_trailer_section: false, fin: false)` for the final response, followed by a five-byte body. The client polls and must see, in this order and with nothing between them: 1. `Event::Headers` whose list contains `:status` `103`, `more_frames` true; 2. `Event::Headers` whose list contains `:status` `200`, `more_frames` true; 3. `Event::Data`, carrying the five bytes; 4. `Event::Finished`. Both header sections are asserted by content, not merely counted: a candidate that delivered the same section twice, or coalesced the two into one, fails on the `:status` values. The refusal leg is the other half and is checked in the same case. Before any of the above, the **client** calls `send_additional_headers` on its own request stream with `is_trailer_section: false`. It must return `FrameUnexpected`: informational responses are a response construct, a request cannot contain one, and the reference rejects it before examining the stream at all. Measured: `Err(FrameUnexpected)`, on a stream that had already had its initial HEADERS sent -- so the refusal is about the direction, not about the state. A server calling `send_additional_headers` on a stream whose initial header section has not been sent is also refused, and that leg belongs to `cap-h3-trailers`, which is where the stream-state rules are gathered. Nothing is asserted about what the 1xx status code *means*, about `Retry-After`, or about Early Hints semantics. The contract is positional: two header sections before the body, both delivered, in order.
score_if cap-h3-informational run_case cap-h3-informational cap cap_h3_informational
# T3: A trailer section after a body, and the three ways the same method must refuse. The positive leg: the server sends `send_response(200, fin=false)`, then a body with `fin=false`, then `send_additional_headers(&[x-checksum: deadbeef], is_trailer_section: true, fin: true)`. The client polls and must see `Event::Headers` (the 200), `Event::Data` (the body, byte for byte), `Event::Headers` again -- carrying `x-checksum` with the value the server sent, and with `more_frames` **false**, because the trailer section closed the stream -- and then `Event::Finished`. The transition of `more_frames` from true on the first section to false on the trailer is asserted: it is how a receiver knows the trailer was a trailer. Three refusals, each `FrameUnexpected`, each measured against the reference: * **a second trailer section on the same stream.** Once a trailer section has gone out the stream is finished with header sections; the repeat call returns `FrameUnexpected` rather than writing a second HEADERS frame. * **before the initial header section.** A server calling `send_additional_headers` on a stream on which it has not yet called `send_response` returns `FrameUnexpected`. This is the leg that is about stream state rather than direction, which is why it sits here rather than in `cap-h3-informational`. * **an unknown stream id.** The same error, not a panic and not a different error: a stream the connection has never seen is refused the same way as one in the wrong state. A client **is** allowed to send trailers, and that asymmetry is the reason this group and `cap-h3-informational` exist separately: `is_trailer_section: true` is the one combination a client may use, and `is_trailer_section: false` is the one it may not.
score_if cap-h3-trailers run_case cap-h3-trailers cap cap_h3_trailers
# T2/T3: The two QPACK byte counters, driven by bytes the verifier writes onto the candidate's own QPACK streams -- because an ordinary request and response leaves them both at zero and a group that read them after a GET would assert `0 == 0` and pass on a `Default::default()`. **Finding the streams (T2, no assumption).** The client's 1-RTT datagrams are decrypted with keys derived from `CLIENT_TRAFFIC_SECRET_0` out of its own keylog, their STREAM frames are decoded, and every client-initiated unidirectional stream (`stream_id % 4 == 2`) carrying `offset == 0` is read for its HTTP/3 stream type byte. The one whose type is `0x02` is the QPACK encoder stream and the one whose type is `0x03` is the QPACK decoder stream. Measured against the reference: control `2`, encoder `6`, decoder `10`, and a GREASE stream `14`. The group reads the type byte rather than hard-coding the ids, so a candidate that opens its unidirectional streams in a different order still passes -- what it may not do is fail to open them. **Driving the counters (T3).** Twenty bytes are written on the encoder stream and twelve on the decoder stream through the client's transport connection, the pair settles, and the server's HTTP/3 connection is polled until it reports `Done`. Then: | | encoder | decoder | | --- | --- | --- | | `server.stats()` | **20** | **12** | | `client.stats()` | 0 | 0 | Five more bytes on the encoder stream, settle and poll again, and the server reports **25** and **12** -- cumulative on the one that moved, untouched on the one that did not. The client's own counters staying at zero throughout is what makes the reading per-connection and per-direction rather than a connection-wide total; the second write is what makes it cumulative rather than a high-water mark or a last-read size. Both endpoints must still be open afterwards: QPACK instructions on a stack with no dynamic table are discarded, and discarding them must not close a critical stream. Exact byte counts are safe to assert here precisely because the verifier chose them. Nothing is asserted about bytes the *candidate's* encoder wrote, which is an encoder policy and not this step's contract.
score_if cap-h3-stats run_case cap-h3-stats cap cap_h3_stats

# ---------------------------------------------------------------------------
# 7. Report.
#
#     reward = gate x score
#
# `score.py` does the arithmetic against the manifest, because the two checks
# that matter are both about groups going missing -- a declared group with no
# recorded result, or a recorded result for a group nobody priced -- and both
# are easier to get right over parsed JSON than over shell word splitting. It
# prints the reward and writes reward_details.json, naming the gate group that
# vetoed the step and quoting what it saw.
#
# If it cannot run at all, that is a verifier defect and not a capability
# result, and the crash path in section 0 says so in those words.
# ---------------------------------------------------------------------------
score_input=$(printf '{"step_num":%d,"tag":"%s","log_dir":"%s","manifest":"/tests/groups.json","crate_dir":"%s","candidate_build":%s,"harness_build":%s,"fixture_ok":%s,"budget_exhausted":%s}\n' \
    "$step_num" "$step_tag" "$log_dir" "$crate_dir" \
    "$([ "$candidate_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$harness_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$fixture_ok" -eq 1 ] && echo true || echo false)" \
    "$([ "$budget_exhausted" -eq 1 ] && echo true || echo false)")

reward=$(printf '%s' "$score_input" | python3 /tests/score.py 2>"$log_dir/score.err")
score_status=$?

case "$reward" in
    0|0.*|1|1.0*) ;;
    *) reward='' ;;
esac

if [ "$score_status" -ne 0 ] || [ -z "$reward" ]; then
    fail_everything "the verifier could not score this step: score.py exited $score_status saying '$(tr -d '\n"\\' < "$log_dir/score.err" | tail -c 300)'. Nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    reported=1
    exit 0
fi

reported=1
report "$reward"
exit 0
